<?php
require 'config.php'; require_role(['student','faculty']); $title='Announcements';$id=(int)($_GET['id']??0);$search=trim($_GET['q']??'');$type=$_GET['type']??'all';if(!in_array($type,['all','General','Important','Event'],true))$type='all';
if($id){$q=$pdo->prepare('SELECT a.*,u.name author FROM announcements a LEFT JOIN users u ON u.id=a.author_id WHERE a.id=?');$q->execute([$id]);$detail=$q->fetch();}else{$sql='SELECT * FROM announcements WHERE 1=1';$p=[];if($search!==''){$sql.=' AND (title LIKE ? OR body LIKE ?)';$like='%'.$search.'%';$p=[$like,$like];}if($type!=='all'){$sql.=' AND type=?';$p[]=$type;}$sql.=' ORDER BY created_at DESC';$q=$pdo->prepare($sql);$q->execute($p);$rows=$q->fetchAll();}
require 'header.php';?>
<?php if($id):?><div class="section"><a class="back-link" href="announcements.php">← All Announcements</a><?php if($detail):?><div class="announcement-detail"><span class="badge"><?=e($detail['type'])?></span><h2><?=e($detail['title'])?></h2><p class="muted">Published <?=date('M d, Y · g:i A',strtotime($detail['created_at']))?><?php if($detail['author']):?> · <?=e($detail['author'])?><?php endif;?></p><div class="announcement-body"><?=nl2br(e($detail['body']))?></div></div><?php else:?><p class="muted">Announcement not found.</p><?php endif;?></div>
<?php else:?><div class="section"><div class="section-intro"><div><h2>Announcements</h2><p class="muted">Important school updates and events.</p></div><form method="get" class="announcement-filter"><input name="q" value="<?=e($search)?>" placeholder="Search announcements"><select name="type"><option value="all">All types</option><option <?= $type==='General'?'selected':''?>>General</option><option <?= $type==='Important'?'selected':''?>>Important</option><option <?= $type==='Event'?'selected':''?>>Event</option></select><button class="btn">Search</button></form></div><?php if(!$rows):?><p class="muted">No announcements found.</p><?php endif;?><?php foreach($rows as $r):?><a class="announcement announcement-link" href="announcements.php?id=<?=e($r['id'])?>"><div class="card-head"><b><?=e($r['title'])?></b><span class="badge"><?=e($r['type'])?></span></div><p><?=e(mb_strimwidth($r['body'],0,180,'…'))?></p><small class="muted"><?=date('M d, Y · g:i A',strtotime($r['created_at']))?></small></a><?php endforeach;?></div><?php endif;?><?php require 'footer.php';?>
